const escape=value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '$' + Math.round(n || 0).toLocaleString('es-CO');
const digits = v => Number(String(v).replace(/\D/g, '')) || 0;
const percent = v => Number(String(v).replace(',', '.')) || 0;
const pct = v => Number(v.toFixed(6)).toLocaleString('es-CO', { maximumFractionDigits: 6, useGrouping: false });
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const enc = s => btoa(unescape(encodeURIComponent(s))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const dec = s => decodeURIComponent(escape(atob(s.replace(/-/g, '+').replace(/_/g, '/'))));
const genId = () => { const d = new Date(); return `AV-${String(d.getFullYear()).slice(2)}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${Math.floor(1000 + Math.random() * 9000)}`; };
const tierFor = (cfg, q) => { const ts = cfg.tiers; for (const t of ts) if (q >= t.min && (t.max == null || t.max === '' || q <= t.max)) return t; return q < ts[0].min ? ts[0] : ts[ts.length - 1]; };
const rangeOf = t => (t.max == null || t.max === '') ? `${t.min}+` : `${t.min}–${t.max}`;
const isYes = v => /^(si|sí|✓|x)$/i.test(String(v).trim());
const isNo = v => /^(-|–|no|)$/i.test(String(v).trim());
const benefitsTable = (cfg, selected) => {
  const heads = cfg.tiers.map((x, j) => ({ name: x.nombre, tag: j === selected ? 'Tu categoría' : '', bg: j === selected ? '#1F4D2B' : '#F2ECDC', fg: j === selected ? '#fff' : '#1F4D2B' }));
  const row = (t, s, vals) => ({ t, s, hasS: !!s, cells: vals.map((v, j) => {
    const hi = j === selected, yes = isYes(v), no = isNo(v);
    return { check: yes, isText: !yes, text: no ? '—' : v, bg: hi ? '#E8EEDD' : 'transparent', fg: no ? '#A7AEA8' : (hi ? '#16361F' : '#2F3A32'), fw: hi ? 600 : 400, dot: hi ? '#1F4D2B' : '#7FA86A' };
  }) });
  return { heads, rows: [
    row('Cantidad de Vites', '', cfg.tiers.map(rangeOf)),
    row('Descuentos en productos Avovite y compra de tus Vites', '', cfg.tiers.map(x => x.desc === x.prod ? `Hasta ${x.desc}%` : `Productos: hasta ${x.prod}% · Compra: hasta ${x.desc}%`)),
    ...cfg.beneficios.map(b => row(b.t, b.s, cfg.tiers.map((_, j) => b.v[j] ?? '-')))
  ] };
};

function getPrices(cfg,selected=null){    const PAL = [{ bg: '#F3F8EE', ac: '#7FA86A', bd: '#E3EDDA' }, { bg: '#E7F1DE', ac: '#4F8A45', bd: '#D5E5C8' }, { bg: '#F8F0DA', ac: '#B08D3C', bd: '#EDE0BC' }, { bg: '#E1EBE3', ac: '#1F4D2B', bd: '#CBDACE' }];
    const pal = x => PAL[cfg.tiers.indexOf(x) % PAL.length];
    const netQ = q => { const x = tierFor(cfg, q), sub = q * cfg.precio, sv = Math.round(sub * x.desc / 100); return { x, net: sub - sv, sv }; };
    const priceIndex = cfg.tiers.findIndex(x => x.nombre === selected);
    const ups = cfg.tiers.slice(1).map(x => { const b = x.min, a = b - 1; if (a < 1) return null; const A = netQ(a), B = netQ(b), selected = cfg.tiers.indexOf(A.x) === priceIndex; return { fromQ: a, toQ: b, fromT: A.x.nombre, toT: B.x.nombre, bg: selected ? '#E8EEDD' : '#fff', bd: selected ? '#1F4D2B' : '#E1E3DA', oneFull: money(cfg.precio), diff: money(B.net - A.net), netA: money(A.net), netB: money(B.net), pA: A.x.desc, pB: B.x.desc, svA: money(A.sv), svB: money(B.sv) }; }).filter(Boolean);
    const pr = {
      benefits: benefitsTable(cfg, priceIndex),
      unitStr: money(cfg.precio), ups,
      tiers: cfg.tiers.map((x, j) => ({ ac: pal(x).ac, bg: j === priceIndex ? '#E8EEDD' : '#fff', bd: j === priceIndex ? '#1F4D2B' : '#E1E3DA', selected: j === priceIndex, selectLabel: `Seleccionar ${x.nombre}`, select: () => this.selectPriceTier(x.nombre), nombre: x.nombre, range: rangeOf(x), desc: x.desc, unitStr: money(cfg.precio), netStr: money(cfg.precio - Math.round(cfg.precio * x.desc / 100)), saveStr: money(cfg.precio * x.desc / 100) })),
      rows: Array.from({ length: 12 }, (_, i) => { const q = i + 1, x = tierFor(cfg, q), sub = q * cfg.precio, sv = Math.round(sub * x.desc / 100); return { q, tier: x.nombre, sub: money(sub), pct: x.desc, net: money(sub - sv), save: money(sv), bg: cfg.tiers.indexOf(x) === priceIndex ? '#E8EEDD' : '#fff', bd: (q > 1 && tierFor(cfg, q - 1) !== x) ? '#C9CFC0' : '#EEF0EA', ac: pal(x).ac }; })
    };

return pr;}
